import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * TASK: Complete CurrencyPurse. The Cash record above it is provided
 * and already works -- do not change it.
 *
 * A purse HAS a list of Cash amounts (composition). It never extends a
 * collection; it keeps a private list and answers questions about it.
 *
 * Rules:
 *   - deposit(cash) ignores null and ignores any Cash whose cents <= 0
 *   - currency codes are compared IGNORING CASE, and are reported upper-case
 *   - balanceOf(code) sums the cents held in that currency (0 when none)
 *   - currencies() returns the distinct upper-case codes, sorted A-Z
 *   - formatted(code) renders the balance as "USD 12.34" (always 2 decimals)
 *
 * Example: deposit(new Cash("usd", 1234)) then deposit(new Cash("USD", 25))
 *   gives balanceOf("Usd") == 1259 and formatted("usd") == "USD 12.59".
 */
record Cash(String currency, long cents) {
}

public class CurrencyPurse {

    private final List<Cash> holdings = new ArrayList<>();

    public void deposit(Cash cash) {
        if (cash == null || cash.cents() <= 0) {
            return;
        }
        holdings.add(cash);
    }

    public int depositCount() {
        return holdings.size();
    }

    public long balanceOf(String currency) {
        if (currency == null) {
            return 0L;
        }
        long total = 0L;
        for (Cash cash : holdings) {
            if (cash.currency().equalsIgnoreCase(currency)) {
                total = total + cash.cents();
            }
        }
        return total;
    }

    public int currencyCount() {
        return currencies().size();
    }

    public List<String> currencies() {
        List<String> codes = new ArrayList<>();
        for (Cash cash : holdings) {
            String code = cash.currency().toUpperCase();
            if (!codes.contains(code)) {
                codes.add(code);
            }
        }
        Collections.sort(codes);
        return codes;
    }

    public String formatted(String currency) {
        long cents = balanceOf(currency);
        String code = currency == null ? "" : currency.toUpperCase();
        return code + " " + (cents / 100) + "." + String.format("%02d", cents % 100);
    }
}
